'use strict';
const $=s=>document.querySelector(s), money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
const norm=s=>s.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/\s+/g,' ');
function number(v){const s=String(v).trim();return Number(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s);}
const cents=v=>Math.round(number(v)*100), total=(q,p)=>Math.round(q*p), fmt=v=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:3}).format(v);
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={lists:[],activeListId:null,items:[],history:[]}, tab='pending', paying=null, draft=null, busy=false, loaded=false;
const add=$('#add');add.elements.date.value=new Date().toLocaleDateString('en-CA');
function latest(product,unit,store){return state.history.filter(h=>norm(h.product)===norm(product)&&h.unit===unit&&(store===undefined||norm(h.store)===norm(store))).sort((a,b)=>b.at.localeCompare(a.at));}
function quote(item){return latest(item.product,item.unit,item.store)[0];}
function controls(disabled){document.querySelectorAll('button,input,select').forEach(e=>e.disabled=disabled);}
async function commit(change){if(busy||!loaded)return false;const before=structuredClone(state);change(state);busy=true;controls(true);$('#status').textContent='Salvando…';try{localStorage.setItem('compras.json',JSON.stringify(state));$('#status').textContent='Salvo neste dispositivo';return true;}catch(e){state=before;$('#status').textContent='Falha ao salvar — tente novamente';alert('Não foi possível salvar os dados. A alteração foi desfeita para manter seu saldo correto.');return false;}finally{busy=false;controls(false);render();}}
function render(){const {spent,missing,estimate,balance}=ShoppingLists.summary(state,quote);$('#list-picker').innerHTML=state.lists.map(l=>`<option value="${esc(l.id)}" ${l.id===state.activeListId?'selected':''}>${esc(l.name)}</option>`).join('');$('#list-context').textContent=ShoppingLists.active(state).name+' · Orçamento e saldo exclusivos desta lista. Histórico de preços compartilhado.';
$('#budget').value=(ShoppingLists.active(state).budget/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});$('#estimate').textContent=money(estimate);$('#spent').textContent=money(spent);$('#balance').textContent=money(balance);$('#balance').classList.toggle('negative',balance<0);$('#coverage').textContent=missing?`${missing} item(ns) sem preço; estimativa parcial`:'Último preço pago em cada loja';$('#forecast').textContent=`Após a estimativa: ${money(balance-estimate)}${missing?' (parcial)':''}`;$('#warning').textContent=balance<0?'O valor pago ultrapassou o orçamento inicial.':balance-estimate<0?'As compras pendentes com preço conhecido ultrapassam o saldo disponível.':'';
const products=[...new Set([...state.items,...state.history].map(i=>i.product))],stores=[...new Set([...state.items,...state.history].map(i=>i.store))];$('#products').innerHTML=products.map(p=>`<option value="${esc(p)}"></option>`).join('');$('#stores').innerHTML=stores.map(p=>`<option value="${esc(p)}"></option>`).join('');
const search=norm($('#search').value);const items=(tab==='history'?state.history:ShoppingLists.items(state).filter(i=>i.done===(tab==='done'))).filter(i=>norm(i.product+' '+i.store).includes(search));
if(!items.length){$('#list').innerHTML='<div class="empty"><b>'+ (search?'Nenhum resultado':tab==='pending'?'Sua próxima compra começa aqui':tab==='done'?'Nenhuma compra confirmada':'Seu histórico começa na primeira compra')+'</b>'+(search?'Tente outro produto ou loja.':'Adicione um produto e marque o checklist quando pagar.')+'</div>';return;}
const groups=new Map();[...items].sort((a,b)=>(a.date||a.at.slice(0,10)).localeCompare(b.date||b.at.slice(0,10))||a.store.localeCompare(b.store,'pt-BR')).forEach(i=>{const key=(i.date||i.at.slice(0,10))+'|'+norm(i.store);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(i);});
$('#list').innerHTML=[...groups.values()].map(group=>{const first=group[0],day=first.date||first.at.slice(0,10);return `<section class="group"><div class="group-title"><div><b>${esc(first.store)}</b><small>${esc(date(day))}</small></div><small>${group.length} item(ns)</small></div>${group.map(i=>{const history=tab==='history',q=history?i.qty:i.done?i.paidQty:i.qty,price=history?i.price:i.done?i.paidPrice:quote(i)?.price;return `<div class="row">${history?'':`<input type="checkbox" data-check="${i.id}" ${i.done?'checked':''} aria-label="${i.done?'Desfazer compra de':'Registrar pagamento de'} ${esc(i.product)}">`}<div class="item-info"><b>${esc(i.product)}</b><small>${esc(fmt(q))} ${esc(i.unit)}${price!==undefined?' · '+esc(money(price))+'/'+esc(i.unit):' · Sem histórico nesta loja'}</small></div><div class="price">${price!==undefined?esc(money(total(q,price))):'—'}<small>${history?'Pago':i.done?'Pago':'Estimado'}</small></div>${!history&&!i.done?`<button class="text-button" data-delete="${i.id}" aria-label="Remover ${esc(i.product)}">Remover</button>`:''}</div>`;}).join('')}</section>`;}).join('');}
$('#budget').addEventListener('change',async e=>{const value=cents(e.target.value);if(!Number.isSafeInteger(value)||value<0){alert('Informe um orçamento válido, maior ou igual a zero.');render();return;}await commit(s=>ShoppingLists.active(s).budget=value);});
async function insert(item){if(await commit(s=>s.items.push(item))){add.elements.product.value='';add.elements.qty.value='1';add.elements.product.focus();}}
add.addEventListener('submit',async e=>{e.preventDefault();if(!loaded||busy)return;const f=add.elements,qty=number(f.qty.value);if(!f.product.value.trim()||!f.store.value.trim()||!Number.isFinite(qty)||qty<=0||qty>1000000){alert('Informe produto, loja e quantidade válida maior que zero.');return;}draft={id:crypto.randomUUID(),listId:state.activeListId,product:f.product.value.trim(),store:f.store.value.trim(),date:f.date.value,qty,unit:f.unit.value,done:false};const current=quote(draft);const byStore=new Map();latest(draft.product,draft.unit).forEach(h=>{if(!byStore.has(norm(h.store)))byStore.set(norm(h.store),h);});const cheaper=[...byStore.values()].filter(h=>norm(h.store)!==norm(draft.store)&&(!current||h.price<current.price)).sort((a,b)=>a.price-b.price)[0];if(cheaper){draft.alternative=cheaper.store;$('#cheaper-text').textContent=`${draft.product}: ${money(cheaper.price)}/${draft.unit} em ${cheaper.store}, registrado em ${date(cheaper.date)}. ${current?'Último preço em '+draft.store+': '+money(current.price)+'/'+draft.unit+'.':'Ainda não há preço registrado em '+draft.store+'.'}`;$('#switch').textContent='Comprar em '+cheaper.store;$('#cheaper').showModal();}else await insert(draft);});
$('#keep').onclick=async()=>{const item={...draft};delete item.alternative;if(await insertAndCheck(item))$('#cheaper').close();};
$('#switch').onclick=async()=>{const item={...draft,store:draft.alternative};delete item.alternative;if(await insertAndCheck(item))$('#cheaper').close();};
async function insertAndCheck(item){const ok=await commit(s=>s.items.push(item));if(ok){add.elements.product.value='';add.elements.qty.value='1';}return ok;}
$('#list').addEventListener('change',async e=>{const id=e.target.dataset.check;if(!id)return;const i=state.items.find(i=>i.id===id);if(!i)return;e.target.checked=i.done;if(i.done){if(confirm('Desfazer esta compra? O valor volta ao saldo e este pagamento sai do histórico.'))await commit(s=>{const x=s.items.find(x=>x.id===id);x.done=false;delete x.paidQty;delete x.paidPrice;s.history=s.history.filter(h=>h.itemId!==id);});return;}paying=id;$('#pay-title').textContent=i.product;$('#pay-store').textContent=i.store+' · '+date(i.date)+' · unidade: '+i.unit;$('#pay').elements.qty.value=fmt(i.qty);$('#pay').elements.price.value=quote(i)?(quote(i).price/100).toFixed(2).replace('.',','):'';updateTotal();$('#payment').showModal();$('#pay').elements.price.focus();});
$('#list').addEventListener('click',async e=>{const id=e.target.closest('[data-delete]')?.dataset.delete;if(id&&confirm('Remover este item pendente da lista?'))await commit(s=>s.items=s.items.filter(i=>i.id!==id));});
function updateTotal(){const q=number($('#pay').elements.qty.value),p=cents($('#pay').elements.price.value);$('#pay-total').textContent=Number.isFinite(q)&&Number.isFinite(p)?money(total(q,p)):'—';}
$('#pay').addEventListener('input',updateTotal);$('#pay').addEventListener('submit',async e=>{e.preventDefault();const q=number(e.target.elements.qty.value),p=cents(e.target.elements.price.value);if(!e.target.elements.price.value.trim()||!Number.isFinite(q)||q<=0||q>1000000||!Number.isSafeInteger(p)||p<0||!Number.isSafeInteger(total(q,p))){alert('Informe quantidade maior que zero e preço válido, maior ou igual a zero.');return;}const ok=await commit(s=>{const i=s.items.find(i=>i.id===paying);i.done=true;i.paidQty=q;i.paidPrice=p;s.history.push({id:crypto.randomUUID(),itemId:i.id,listId:i.listId,product:i.product,store:i.store,unit:i.unit,qty:q,price:p,date:i.date,at:new Date().toISOString()});});if(ok)$('#payment').close();});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));render();});$('#search').addEventListener('input',render);
async function init(){controls(true);try{const data=JSON.parse(localStorage.getItem('compras.json')||'{"items":[],"history":[]}');state=ShoppingLists.migrate(data);loaded=true;controls(false);$('#status').textContent='Salvo neste dispositivo';render();if(data.schemaVersion!==2)await commit(()=>{});}catch(e){$('#status').textContent='Não foi possível carregar. Reabra o aplicativo para tentar novamente.';}}
$('#list-picker').addEventListener('change',async e=>{const id=e.target.value;if(state.lists.some(l=>l.id===id)){await commit(s=>s.activeListId=id);$('#search').value='';render();}});
$('#new-list').onclick=()=>{$('#list-form').reset();$('#list-modal').showModal();$('#list-form').elements.name.focus();};
$('#list-form').addEventListener('submit',async e=>{e.preventDefault();const name=e.target.elements.name.value.trim(),budget=cents(e.target.elements.budget.value);if(!name||!Number.isSafeInteger(budget)||budget<0){alert('Informe um nome e orçamento válido, maior ou igual a zero.');return;}const id=crypto.randomUUID();if(await commit(s=>{s.lists.push({id,name,budget});s.activeListId=id;})){$('#list-modal').close();$('#search').value='';render();}});
$('#rename-list').onclick=async()=>{const name=prompt('Nome da lista:',ShoppingLists.active(state).name);if(name===null)return;if(!name.trim()||name.trim().length>100){alert('Use um nome entre 1 e 100 caracteres.');return;}await commit(s=>ShoppingLists.active(s).name=name.trim());};
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js');init();
